SC.onec=()=>`<div class="hd"><div><h2>Обмен с 1С</h2><p>Первичка ведётся в портале — менеджеры и бухгалтер работают здесь. В 1С в реальном времени уходят счета, реализации, акты аренды, поступления и движение денег. Главбух проверяет всё в привычной 1С.</p></div><div class="btns"><span class="live"><i></i>синхронизация · ${NOW}</span></div></div>
 <div class="strip"><div><small>Документов сегодня</small><b>${ONEC.length}</b></div><div><small>Ошибок обмена</small><b class="ok">0</b></div><div><small>Направление</small><b>портал → 1С</b><span>справочники ← 1С</span></div><div><small>Отчётность</small><b>из 1С</b><span>в госорганы — как сейчас</span></div></div>
 <div class="g21"><div class="pan"><h3>Что ушло в 1С сегодня</h3><div class="tw"><table class="t"><thead><tr><th>Время</th><th>Документ 1С</th><th>Основание</th><th class="r">Сумма, ₸</th><th>Статус</th></tr></thead><tbody>${ONEC.map(r=>`<tr><td class="mono">${r[0]}</td><td><b>${r[1]}</b></td><td>${esc(r[2])}</td><td class="r">${r[3]}</td><td>${tag(r[4],r[4]==='ок'?'g':'w')}</td></tr>`).join('')}</tbody></table></div></div>
 <div><div class="pan"><h3>Роли и связь</h3><div class="kv"><span>Менеджер продаж</span><b>сделка → счёт</b></div><div class="kv"><span>Менеджер аренды</span><b>аренда → акт</b></div><div class="kv"><span>Бухгалтер</span><b>оплаты, сверка</b></div><div class="kv"><span>Главбух</span><b>проверка в 1С</b></div><button class="bt full" onclick="toast('Сверка за ноябрь: портал = 1С, расхождений нет.')">Сверка портал ↔ 1С</button></div>
 ${said('«Все отчёты, которые бухгалтер создаёт в CRM, должны уходить в 1С, чтобы главбух мог проверять полностью. Связь должна быть полная»')}</div></div>`;
let bxStep=2;
SC.bitrix=()=>`<div class="hd"><div><h2>Переезд из Битрикс24</h2><p>Забираем всё: клиентов, сделки, компании, историю. Повторы склеиваем по телефону и ИИН. После переезда Битрикс24 можно отключить — экономия тарифа «Профессиональный» каждый месяц.</p></div></div>
 <div class="stepr">${['Выгрузка','Сопоставление полей','Склейка дублей','Загрузка','Проверка','Битрикс отключён'].map((s,i)=>`<span class="${i<=bxStep?'on':''}">${i+1}. ${s}</span>`).join('')}</div>
 <div class="g21"><div class="pan"><h3>Что переносим</h3><table class="t"><thead><tr><th>Данные</th><th class="r">В Битрикс24</th><th class="r">После склейки</th><th>Куда</th></tr></thead><tbody>${[['Контакты',3412,2986,'Клиенты'],['Компании',214,198,'Клиенты (юрлица)'],['Сделки',1268,1268,'История клиента'],['Звонки и комментарии',8940,8940,'Лента карточки'],['Файлы и договоры',1120,1120,'Документы клиента']].map(r=>`<tr><td>${r[0]}</td><td class="r">${fmt(r[1])}</td><td class="r">${fmt(r[2])}</td><td>${r[3]}</td></tr>`).join('')}</tbody></table><div class="btns l"><button class="bt p" onclick="bxStep=Math.min(5,bxStep+1);render()">Следующий шаг</button></div></div>
 <div>${said('«Мы купили тариф Профессиональный… по продажам идут, но мы их не контролируем. А по аренде он вообще бесполезен, как выяснилось»')}${said('«А наши предыдущие клиенты — они не войдут в CRM?» — «Мы их перенесём, синхронизируем, всё заберём»')}</div></div>`;
const PERM=['Пульт и графики','Аренда: прицепы и карта','Проверка ИИН','Продажи: воронка','Цены и скидки','Деньги и оплаты','Должники и суды','Обмен с 1С'];
const PM={'Собственник':'11111111','Менеджер продаж':'00011000','Менеджер аренды':'01110000','Бухгалтер':'00000111','Главбух':'00000101','Юрист':'00100010'};
SC.roles=()=>`<div class="hd"><div><h2>Роли и права</h2><p>Каждый видит своё. Продажи и аренда — разные отделы, бухгалтерия связана с обоими. Права — галочками, журнал: кто, когда, что изменил.</p></div></div>
 <div class="pan"><div class="tw"><table class="t perm"><thead><tr><th>Роль</th>${PERM.map(p=>`<th class="c">${p}</th>`).join('')}</tr></thead><tbody>${Object.keys(PM).map(r=>`<tr><td><b>${r}</b><br><small>${esc(ROLES[r].note)}</small></td>${PM[r].split('').map((v,i)=>`<td class="c"><span class="pm ${v==='1'?'on':''}" onclick="this.classList.toggle('on');toast('Право «${PERM[i]}» изменено — запись в журнале.')">${v==='1'?'✓':''}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div></div>
 <div class="g2"><div class="pan"><h3>Журнал действий</h3><table class="t sm"><tbody>${[['18:20','Айдос','отправил КП С-902 в WhatsApp'],['17:41','Сабина','продлила аренду А-3312'],['16:30','Алия','провела оплату С-893 → 1С'],['15:02','Ернар','перевёл Д-223 в «Иск подан»'],['12:10','Валерий','изменил тариф ПР-06']].map(r=>`<tr><td class="mono">${r[0]}</td><td><b>${r[1]}</b></td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div>
 <div class="pan"><h3>Пользователи</h3><p>Без ограничений по количеству: 4 менеджера продаж, менеджеры аренды, бухгалтерия, юрист, будущий РОП — платить за каждого не нужно.</p><div class="kv"><span>Сервер</span><b>~5–10 $ / мес</b></div><div class="kv"><span>Резервные копии</span><b>ежедневно</b></div></div></div>`;
SC.launch=()=>`<div class="hd"><div><h2>Стоимость</h2><p>Своя система под аренду и продажи прицепов. Платите один раз — код, данные и сервер ваши. Без абонплаты и без оплаты за пользователей.</p></div></div>
 <div class="g2"><div class="pan price"><h3>Портал · 2 500 000 ₸ · 4–6 недель</h3>
 ${['Аренда: карта парковок и GPS, прицепы, аренды и календарь, возвраты и просрочки, камеры, триггеры','Клиенты: проверка по ИИН, договор и подпись, должники и суды','Продажи: воронка, карточка клиента с историей, калькулятор → КП в WhatsApp','Каналы: WhatsApp (Green API), Telegram, IP-телефония','Связка с вашим приложением по API','Статистика и графики, роли, журнал','Переезд из Битрикс24, сервер, бэкапы, обучение, 3 месяца поддержки'].map(x=>`<div class="ck">✓ ${x}</div>`).join('')}</div>
 <div><div class="pan"><h3>Оплата по этапам</h3><table class="t"><tbody><tr><td>Старт · 30%</td><td class="r">${tg(750000)}</td></tr><tr><td>База на ваших данных · 40%</td><td class="r">${tg(1000000)}</td></tr><tr><td>Сдача и ключи · 30%</td><td class="r">${tg(750000)}</td></tr><tr class="sum"><td><b>Портал</b></td><td class="r"><b>${tg(2500000)}</b></td></tr><tr><td>Интеграция с 1С (портал → 1С)</td><td class="r">+${tg(800000)}</td></tr></tbody></table></div>
 <div class="pan"><h3>Не входит</h3><div class="ck no">· Клиентское приложение — у вашего разработчика или отдельным проектом</div><div class="ck no">· Замки, трекеры, камеры — оборудование ваше</div><div class="ck no">· Тарифы WhatsApp, телефонии, проверки ИИН — по факту</div></div></div></div>`;
/* ===== Каркас: верхние вкладки + левая колонка ===== */
function searchDemo(v){if(!v)return;const q=v.toLowerCase();const t=FLEET.find(x=>x.id.toLowerCase().includes(q));if(t&&allowed('fleet')){openTr(t.id);return}const c=CLIENTS.find(x=>(x.n+x.iin+x.ph+x.id).toLowerCase().includes(q));if(c&&allowed('client')){curCl=c.id;go('client');return}toast('Не найдено. Попробуйте: «ПР-04», «Асхат», «870512».')}
function renderRoles(){const r=document.getElementById('roles');if(r)r.innerHTML=Object.entries(ROLES).map(([k,v])=>`<div class="role" onclick="enter('${esc(k)}')"><div class="rav">${esc(v.av)}</div><div><b>${esc(k)}</b><span>${esc(v.n)} · ${esc(v.note)}</span></div></div>`).join('');const s=document.getElementById('rsel');if(s)s.innerHTML=Object.keys(ROLES).map(k=>`<option>${esc(k)}</option>`).join('')}
const allowed=k=>ROLES[role].s.indexOf(k)>=0;
function enter(k){role=ROLES[k]?k:'Собственник';document.getElementById('gate').classList.add('hidden');document.getElementById('app').classList.remove('hidden');const s=document.getElementById('rsel');if(s)s.value=role;document.getElementById('me').textContent=ROLES[role].av;if(!allowed(cur))cur=ROLES[role].s[0];build()}
function switchRole(k){role=k;document.getElementById('me').textContent=ROLES[role].av;const s=document.getElementById('rsel');if(s)s.value=role;if(!allowed(cur))cur=ROLES[role].s[0];build();toast(`Роль <b>${esc(role)}</b>: ${esc(ROLES[role].note)}.`)}
function buildRail(){document.getElementById('rail').innerHTML=SEC.filter(s=>s.sub.some(x=>allowed(x[0]))).map(s=>`<a class="ri ${s.k===SECOF[cur]?'on':''}" onclick="go('${s.sub.filter(x=>allowed(x[0]))[0][0]}')"><span>${s.n}</span></a>`).join('');
 const S=SEC.find(x=>x.k===SECOF[cur]);document.getElementById('sub').innerHTML=`<h4>${esc(S.n)}</h4>`+S.sub.filter(x=>allowed(x[0])).map((x,i)=>`<a class="${x[0]===cur?'on':''}" onclick="go('${x[0]}')"><code>${String(i+1).padStart(2,'0')}</code>${esc(x[1])}</a>`).join('')+`<div class="shint"><b>${esc(role)}</b><br>${esc(ROLES[role].note)}</div>`}
function build(){buildRail();render()}
function render(){const f=SC[cur]||SC.dash;document.getElementById('ttl').textContent=SUBN[cur]||'ТрейлерГо';document.getElementById('content').innerHTML=`<div class="screen">${f()}</div>`;buildRail();try{history.replaceState(null,'','?s='+cur)}catch(e){}}
function go(k){if(!allowed(k)){toast('Этой роли раздел недоступен — так работают права. Переключите роль справа вверху.');return}cur=k;build();const c=document.querySelector('.content');if(c)c.scrollTop=0}
function openM(t,s,b){document.getElementById('mt').innerHTML=t;document.getElementById('ms').innerHTML=s;document.getElementById('mbody').innerHTML=b;document.getElementById('mbg').classList.add('show')}
function closeM(){document.getElementById('mbg').classList.remove('show')}
let tt=null;function toast(m){const t=document.getElementById('toast');t.innerHTML=m;t.classList.add('show');clearTimeout(tt);tt=setTimeout(()=>t.classList.remove('show'),6400)}
let theme='light';function applyTheme(){document.body.classList.toggle('dark',theme==='dark')}function toggleTheme(){theme=theme==='dark'?'light':'dark';applyTheme()}
const TOUR=[['dash','1 · Пульт: прицепы, просрочки, выручка, менеджеры.'],['map','2 · Карта парковок и GPS каждого прицепа.'],['cams','3 · Камеры парковки: выезд и въезд по событиям.'],['kyc','4 · Проверка клиента по ИИН: должник — отказ.'],['contract','5 · Договор с подписью → оплата → замок открыт.'],['returns','6 · Просрочки: штраф, напоминания, продление.'],['triggers','7 · Триггеры работают сами.'],['debtors','8 · Должники и суды по стадиям.'],['funnel','9 · Воронка продаж: обращения из всех каналов.'],['calc','10 · Калькулятор прицепа → КП в WhatsApp.'],['client','11 · Повторный клиент: вся история в одной карточке.'],['stats','12 · Графики: обращения, конверсия, менеджеры.'],['app','13 · Ваше приложение ↔ портал по API.'],['onec','14 · Первичка → 1С в реальном времени.'],['launch','15 · 2,5 млн + 1С 800 тыс., 4–6 недель.']];
let ti=-1,tRun=false;function tour(){if(tRun){tRun=false;return}tRun=true;ti=-1;step()}
function step(){if(!tRun)return;ti++;if(ti>=TOUR.length){tRun=false;toast('Сценарий закончен — всё кликается.');return}const [k,m]=TOUR[ti];if(!allowed(k))switchRole('Собственник');cur=k;build();toast('<b>'+m+'</b>');setTimeout(step,5200)}
(function(){renderRoles();applyTheme();const s=document.getElementById('rsel');if(s)s.addEventListener('change',e=>switchRole(e.target.value));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeM();tRun=false}});
 let q='';try{q=new URLSearchParams(location.search).get('s')||''}catch(e){}
 if(q&&SECOF[q]){const r=Object.keys(ROLES).find(k=>ROLES[k].s.indexOf(q)>=0);if(r){cur=q;enter(r)}}})();
function stopTour(){tRun=false}
